INSERT INTO "public"."t_operation_log" OVERRIDING SYSTEM VALUE VALUES (1711, '文章模块', '新增或修改', '/admin/articles', 'com.aurora.controller.ArticleController.saveOrUpdateArticle', '保存和修改文章', '[{"articleContent":"使用python实现了一个简易的贪吃蛇游戏,为了让更多人能体会到python给我们带来的方便和乐趣,源代码包含了详细的注释,同时也采用了更简单和易于理解的方式来实现贪吃蛇游戏.\n下面为代码，仅供参考：\n\nimport pygame,sys,time,random\nfrom pygame.locals import *\n# 定义颜色变量\nredColour = pygame.Color(255,0,0)\nblackColour = pygame.Color(0,0,0)\nwhiteColour = pygame.Color(255,255,255)\ngreyColour = pygame.Color(150,150,150)\n\n\n# 定义gameOver函数\ndef gameOver(playSurface):\n    gameOverFont = pygame.font.Font(''arial.ttf'',72)\n    gameOverSurf = gameOverFont.render(''Game Over'', True, greyColour)\n    gameOverRect = gameOverSurf.get_rect()\n    gameOverRect.midtop = (320, 10)\n    playSurface.blit(gameOverSurf, gameOverRect)\n    pygame.display.flip()\n    time.sleep(5)\n    pygame.quit()\n    sys.exit()\n\n\n# 定义main函数\ndef main():\n    # 初始化pygame\n    pygame.init()\n    fpsClock = pygame.time.Clock()\n    # 创建pygame显示层\n    playSurface = pygame.display.set_mode((640,480))\n    pygame.display.set_caption(''Raspberry Snake'')\n\n    # 初始化变量\n    snakePosition = [100,100]\n    snakeSegments = [[100,100],[80,100],[60,100]]\n    raspberryPosition = [300,300]\n    raspberrySpawned = 1\n    direction = ''right''\n    changeDirection = direction\n    while True:\n        # 检测例如按键等pygame事件\n        for event in pygame.event.get():\n            if event.type == QUIT:\n                pygame.quit()\n                sys.exit()\n            elif event.type == KEYDOWN:\n                # 判断键盘事件\n                if event.key == K_RIGHT or event.key == ord(''d''):\n                    changeDirection = ''right''\n                if event.key == K_LEFT or event.key == ord(''a''):\n                    changeDirection = ''left''\n                if event.key == K_UP or event.key == ord(''w''):\n                    changeDirection = ''up''\n                if event.key == K_DOWN or event.key == ord(''s''):\n                    changeDirection = ''down''\n                if event.key == K_ESCAPE:\n                    pygame.event.post(pygame.event.Event(QUIT))\n        # 判断是否输入了反方向\n        if changeDirection == ''right'' and not direction == ''left'':\n            direction = changeDirection\n        if changeDirection == ''left'' and not direction == ''right'':\n            direction = changeDirection\n        if changeDirection == ''up'' and not direction == ''down'':\n            direction = changeDirection\n        if changeDirection == ''down'' and not direction == ''up'':\n            direction = changeDirection\n        # 根据方向移动蛇头的坐标\n        if direction == ''right'':\n            snakePosition[0] += 20\n        if direction == ''left'':\n            snakePosition[0] -= 20\n        if direction == ''up'':\n            snakePosition[1] -= 20\n        if direction == ''down'':\n            snakePosition[1] += 20\n        # 增加蛇的长度\n        snakeSegments.insert(0,list(snakePosition))\n        # 判断是否吃掉了树莓\n        if snakePosition[0] == raspberryPosition[0] and snakePosition[1] == raspberryPosition[1]:\n            raspberrySpawned = 0\n        else:\n            snakeSegments.pop()\n        # 如果吃掉树莓，则重新生成树莓\n        if raspberrySpawned == 0:\n            x = random.randrange(1,32)\n            y = random.randrange(1,24)\n            raspberryPosition = [int(x*20),int(y*20)]\n            raspberrySpawned = 1\n        # 绘制pygame显示层\n        playSurface.fill(blackColour)\n        for position in snakeSegments:\n            pygame.draw.rect(playSurface,whiteColour,Rect(position[0],position[1],20,20))\n            pygame.draw.rect(playSurface,redColour,Rect(raspberryPosition[0], raspberryPosition[1],20,20))\n\n        # 刷新pygame显示层\n        pygame.display.flip()\n        # 判断是否死亡\n        if snakePosition[0] > 620 or snakePosition[0] < 0:\n            gameOver(playSurface)\n        if snakePosition[1] > 460 or snakePosition[1] < 0:\n            for snakeBody in snakeSegments[1:]:\n                if snakePosition[0] == snakeBody[0] and snakePosition[1] == snakeBody[1]:\n                    gameOver(playSurface)\n        # 控制游戏速度\n        fpsClock.tick(5)\n\n\nif name == \"main\":\n    main()\n效果图：\n![image.png](https://example-bucket.oss-cn-shanghai.aliyuncs.com/articles/3e9ac5b740861d1d9543dc14aa547892.png)","articleCover":"https://example-bucket.oss-cn-shanghai.aliyuncs.com/articles/bf9f4cca1f8e1e4f0c18e5dd2d385ed1.jpg","articleTitle":"Python实现简易贪吃蛇","categoryName":"后端","isFeatured":0,"isTop":0,"status":1,"tagNames":["python","贪吃蛇"],"type":2}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '演示账号', '172.17.0.1', '内网IP|内网IP', '2023-03-07 19:48:52', NULL);
INSERT INTO "public"."t_operation_log" OVERRIDING SYSTEM VALUE VALUES (1712, '文章模块', '上传', '/admin/articles/images', 'com.aurora.controller.ArticleController.saveArticleImages', '上传文章图片', 'file', 'POST', '{"code":20000,"data":"https://example-bucket.oss-cn-shanghai.aliyuncs.com/articles/12d887b0ac65f05883a06ab7a6f4a5f9.jpg","flag":true,"message":"操作成功"}', 1, '演示账号', '172.17.0.1', '内网IP|内网IP', '2023-03-07 19:51:36', NULL);
INSERT INTO "public"."t_operation_log" OVERRIDING SYSTEM VALUE VALUES (1713, '文章模块', '新增或修改', '/admin/articles', 'com.aurora.controller.ArticleController.saveOrUpdateArticle', '保存和修改文章', '[{"articleContent":"编者按：编程语言有上千种，但是流行的不过10来种，那些我们经常使用的编程语言都是谁在什么时候创造出来的呢？Casper Beyer为我们进行了整理。\n\n1800年\n\nJoseph Marie Jacquard教会了一台织布机读穿孔卡片，制造出了第一个高度多线程的处理单元。他的发明受到了预见天网（Skynet）诞生的纺织工人的强烈反对。\n\n1842年\n\nAda Lovelace（英国诗人拜伦之女）对随后被认定是发布的第一个计算机程序的笔记本高贵和潦草感到厌烦，因为稍微有点不便的是当时还没有计算机呢。\n\n1936年\n\n阿兰·图灵发明了一切，但英国法庭却并不认可，还判处对他进行化学阉割。\n\n女皇后来宽恕了他，但不幸的是当时他已经过世很久了。\n\n1936年\n\nAlonzo Church（算法理论重要奠基人）跟图灵一样也发明了一切，但他是对岸那边的，并没有被阉割。\n\n1957年\n\nJohn Backus创建了FORTRAN语言，这是真正的程序员使用的第一种语言。\n\n1959年\n\nGrace Hopper发明了第一门针对企业面向商业的编程语言，并且把这门语言叫做“面向商业的通用语言（common business-oriented language）”，简称COBOL。\n\n1964年\n\nJohn Kemeny 和 Thomas Kurtz 认为编程太难了，需要回归本源，他们把自己的编程语言叫做BASIC。\n\n1970年\n\nNiklaus Wirth开发了多种语言，最后流行起来的是PASCAL。他喜欢开发语言。\n\n他还发明了让摩尔定律变得过时的Wirth定律（软件变慢的速度比硬件变快的速度更快），因为软件开发者会编写出连大型主机也没法跟上的臃肿软件。这在后来被证明是正确的——在Electron.js被发明出来后。\n\n1972年\n\nDennis Ritchie在贝尔实验室上班上到无聊了，于是他决定写出带有花括号的C语言，这门语言取得了巨大成功。随后他又增加了分段错误等对开发者友好的功能来辅助提高生产率。\n\n折腾完这门语言之后他还有时间，于是他跟在贝尔实验室的伙计决定给C语言做个演示程序，结果他们弄出了一个操作系统，UNIX。\n\n1980年\n\nAlan Kay发明了一门面向对象语言，他把这门语言叫做Smalltalk，在Smalltalk中一切都是对象，甚至一个对象也是对象。没人真正搞得清楚small talk是什么意思。\n\n1987年\n\nLarry Wall有宗教经验，他成为了一名牧师，并且把Perl变成了一种教义。\n\n1983年\n\nJean Ichbiah注意到Ada Lovelace的程序从来都没有实际运行过，决定以她的名字开发一门语言，但是这门语言还是没有跑起来。\n\n1986年\n\nBrac Box 和 Tol Move决定在Smalltalk的基础上制作一个C语言的不可读版本，他们把这门语言叫做Objective-C，但是没人弄得清楚它的语法。\n\n1983年\n\nBjarne Stroustrup回到未来，注意到C在编译方面花的时间还不够多，于是他把自己能想到的每一项功能都增加了进去，然后称之为C++。\n\n每一个地方的程序员都接受了它，因为这样他们在工作的时候找借口看阿猫阿狗视频和xkcd漫画就显得比较有诚意了。\n\n1991年\n\nGuido van Rossum不喜欢花括号，于是他发明了Python，语法选择的灵感来源自Monty Python（巨蟒剧团）和Flying Circus（飞行马戏团）。\n\n1993年\n\nRoberto Ierusalimschy和他的朋友认为自己需要一个巴西本地化的脚本语言，在本地化期间发生了一个错误，这个错误会把指针从1而不是0开始计算，他们把这门语言叫做Lua。\n\n1994年\n\nRasmus Lerdorf给他个人主页的CGI脚本做了一个模板引擎，后来他把自己的资料都放到了网上。\n\n世界决定将这些东西用到一切，Rasmus于是匆忙地将一些数据库绑定做了进去，并把这门语言叫做PHP。\n\n1995年\n\nYukihiro Matsumoto不是很高兴，因为他注意到其他程序员不是很高兴。他创建了Ruby来让程序员高兴。在他创建了Ruby后“Matz”高兴了，Ruby社区高兴了，每个人都高兴了。\n\n1995年\n\nBrendan Eich利用周末时间设计了一门语言，打算用这门语言来为全世界的每一个主流浏览器乃至于最终的Skynet都提供动力。他先是找到了Netscape然后说这门语言叫做LiveScript，但在代码评审期间Java变得流行起来，所以他们决定最好还是用花括号，然后就把它更名为JavaScript。\n\n结果表明，Java却是一个会让他们惹上麻烦的商标，JavaScript随后更名为ECMAScript，但大家还是把它叫做JavaScript。\n\n1996年\n\nJames Gosling发明了Java，第一们真正过于繁琐的面向对象语言，在这里设计模式完全压倒了实用主义。\n\n于是就诞生了超级有效的管理器提供商、容器提供商、服务提供商、单一管理器提供商模式。\n\n2001年\n\nAnders Hejlsberg重新发明了Java然后把它叫做C#，因为用C来编程感觉要比Java酷。每个人都喜欢这个新版本的Java，因为它完全不像Java。\n\n2005年\n\nDavid Hanselmeyer Hansen创建了一个web框架叫做Ruby on Rails，从此大家不再记得Ruby和Rails是两个独立的东西了。\n\n2006年\n\nJohn Resig为JavaScript写了一个帮助库，每个人都以为那是一门语言，从此从互联网上拷贝粘贴jQuery代码就成为了一门职业。\n\n2009年\n\nKen Thompson 和 Rob Pike 决定做一门类似C那样的语言，但要有更安全的装置，还要有更好的卖相，并且把Gopher（囊鼠）作为吉祥物。\n\n他们把这门语言成为Go，并把它做成开源然后另外卖Gopher商标的护膝和头盔作为收入来源。\n\n2010年\n\nGraydon Hoare也想把语言做成C那样，他称之为Rust。每个人都要求马上用Rust把软件的每一块都重写一遍。Graydon希望做点更有亮点的事情，于是开始为苹果开发Swift。\n\n2012年\n\nAnders Hjelsberg希望在web浏览器里面写C#，于是他设计出TypeScript，这东西其实是JavaScript，但里面有了更多的Java的东西。\n\n2013年\n\nJeremy Ashkenas想要像Ruby开发者一样快乐，于是他创建了CoffeeScript，这东西编译后像JavaScript但是样子又更像Ruby。Jerry从来都没有变得像Matz和Ruby开发者那样真正快乐。\n\n2014年\n\nChris Lattner做Swift的时候，其主要的设计目标就是不要成为Objective-C，最后它看起来像Java。","articleCover":"https://example-bucket.oss-cn-shanghai.aliyuncs.com/articles/12d887b0ac65f05883a06ab7a6f4a5f9.jpg","articleTitle":"编程语言简史：都是谁在什么时候创造出来的呢？","categoryName":"杂谈","isFeatured":0,"isTop":0,"status":1,"tagNames":["编程语言"],"type":2}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '演示账号', '172.17.0.1', '内网IP|内网IP', '2023-03-07 19:51:40', NULL);
INSERT INTO "public"."t_operation_log" OVERRIDING SYSTEM VALUE VALUES (1714, '文章模块', '上传', '/admin/articles/images', 'com.aurora.controller.ArticleController.saveArticleImages', '上传文章图片', 'file', 'POST', '{"code":20000,"data":"https://example-bucket.oss-cn-shanghai.aliyuncs.com/articles/09d3285df2b065db0f5be6b97126e3f8.jpg","flag":true,"message":"操作成功"}', 1, '演示账号', '172.17.0.1', '内网IP|内网IP', '2023-03-07 19:55:37', NULL);
INSERT INTO "public"."t_operation_log" OVERRIDING SYSTEM VALUE VALUES (1715, '文章模块', '新增或修改', '/admin/articles', 'com.aurora.controller.ArticleController.saveOrUpdateArticle', '保存和修改文章', '[{"articleContent":"疫情数据爬取与可视化展示\n使用Python爬取腾讯新闻疫情数据，并使用pyecharts可视化，绘制国内、国际日增长人数地图，matplotlib绘制方寸图。\n\n随笔记录所的所学，此博客为我记录文章所用，发布到此，仅供网友阅读参考。作者:北山啦\n\n写在前面：这个已经不是什么新鲜的话题了，所以请大佬勿喷\n\n文章目录\n疫情数据爬取与可视化展示\n1. 疫情数据抓取\n2. 初步分析\n3. 数据处理\n3.1 国内各省疫情数据提取\n3.2 国际疫情数据提取\n3.3 数据整合\n4. 可视化展示\n4.1 国内疫情态势可视化\n4.2 国际疫情态势可视化\n4.3 国内疫情方寸间\n4.4 国际疫情方寸间\n参考链接\n导入相关模块\n\nimport time\nimport json\nimport requests\nfrom datetime import datetime\nimport pandas as pd\nimport numpy as np\n1. 疫情数据抓取\n通过腾讯新闻公布的数据进行爬取\n\n网址:https://news.qq.com/zt2020/page/feiyan.htm#/\n\n对于静态网页，我们只需要把网页地址栏中的url传到get请求中就可以轻松地获取到网页的数据。 对于动态网页抓取的关键是先分析网页数据获取和跳转的逻辑，再去写代码 。\n\n右击检查，选择Network，Ctrl+R即可\n在这里插入图片描述\n\n# 定义抓取数据函数:https://beishan.blog.csdn.net/\ndef Domestic():\n    url = ''https://view.inews.qq.com/g2/getOnsInfo?name=disease_h5''\n    reponse = requests.get(url=url).json()\n    data = json.loads(reponse[''data''])\n    return data\n\n\ndef Oversea():\n    url = ''https://view.inews.qq.com/g2/getOnsInfo?name=disease_foreign''\n    reponse = requests.get(url=url).json()\n    data = json.loads(reponse[''data''])\n    return data\n\n\ndomestic = Domestic()\noversea = Oversea()\n\nprint(domestic.keys())\nprint(oversea.keys())\ndict_keys([''lastUpdateTime'', ''chinaTotal'', ''chinaAdd'', ''isShowAdd'', ''showAddSwitch'', ''areaTree''])\ndict_keys([''foreignList'', ''globalStatis'', ''globalDailyHistory'', ''importStatis'', ''countryAddConfirmRankList'', ''countryConfirmWeekCompareRankList'', ''continentStatis''])\n2. 初步分析\n提取各地区数据明细\n\n# 提取各地区数据明细\nareaTree = domestic[''areaTree'']\n# 查看并分析具体数据\nareaTree\n提取国外地区数据明细\n\n# 提取国外地区数据明细\nforeignList = oversea[''foreignList'']\n# 查看并分析具体数据\nforeignList\n就可以看到在json数据存储的结构了\n\n3. 数据处理\n3.1 国内各省疫情数据提取\n# Adresss：https://beishan.blog.csdn.net/\nchina_data = areaTree[0][''children''] \nchina_list = []\nfor a in range(len(china_data)):\n    province = china_data[a][''name'']  \n    confirm = china_data[a][''total''][''confirm''] \n    heal = china_data[a][''total''][''heal'']  \n    dead = china_data[a][''total''][''dead'']  \n    nowConfirm = confirm - heal - dead \n    china_dict = {\n   } \n    china_dict[''province''] = province  \n    china_dict[''nowConfirm''] = nowConfirm \n    china_list.append(china_dict) \n\nchina_data = pd.DataFrame(china_list) \nchina_data.to_excel(\"国内疫情.xlsx\", index=False) #存储为EXCEL文件\nchina_data.head()\nprovince\tnowConfirm\n0\t香港\t323\n1\t上海\t40\n2\t四川\t34\n3\t台湾\t30\n4\t广东\t29\n3.2 国际疫情数据提取\nworld_data = foreignList  \nworld_list = []  \n\nfor a in range(len(world_data)):\n    # 提取数据\n    country = world_data[a][''name'']\n    nowConfirm = world_data[a][''nowConfirm'']  \n    confirm = world_data[a][''confirm'']\n    dead = world_data[a][''dead'']  \n    heal = world_data[a][''heal''] \n    # 存放数据\n    world_dict = {\n   }\n    world_dict[''country''] = country\n    world_dict[''nowConfirm''] = nowConfirm\n    world_dict[''confirm''] = confirm\n    world_dict[''dead''] = dead\n    world_dict[''heal''] = heal\n    world_list.append(world_dict)\n\nworld_data = pd.DataFrame(world_list)\nworld_data.to_excel(\"国外疫情.xlsx\", index=False)\nworld_data.head()\ncountry\tnowConfirm\tconfirm\tdead\theal\n0\t美国\t7282611\t30358880\t552470\t22523799\n1\t西班牙\t193976\t3212332\t72910\t2945446\n2\t法国\t2166003\t2405255\t57671\t181581\n3\t秘鲁\t111940\t422183\t19408\t290835\n4\t英国\t90011\t104145\t13759\t375\n3.3 数据整合\n将国内数据和海外数据合并\n\n查询数据中是否含有中国疫情数据\n\nworld_data.loc[world_data[''country''] == \"中国\"]\ncountry\tnowConfirm\tconfirm\tdead\theal\n从新增areaTree中提取中国数据，并添加至world_data\n\nconfirm = areaTree[0][''total''][''confirm'']  # 提取中国累计确诊数据\nheal = areaTree[0][''total''][''heal'']  # 提取中国累计治愈数据\ndead = areaTree[0][''total''][''dead'']  # 提取中国累计死亡数据\nnowConfirm = confirm - heal - dead  # 计算中国现有确诊数量\n\nworld_data = world_data.append(\n    {\n   \n        ''country'': \"中国\",\n        ''nowConfirm'': nowConfirm,\n        ''confirm'': confirm,\n        ''heal'': heal,\n        ''dead'': dead\n    },\n    ignore_index=True)\n再次查询数据中是否含有中国疫情数据\n\nworld_data.loc[world_data[''country''] == \"中国\"]\ncountry\tnowConfirm\tconfirm\tdead\theal\n161\t中国\t518\t102479\t4849\t97112\n4. 可视化展示\n4.1 国内疫情态势可视化\n导入pyecharts相关库\n\nimport pyecharts.options as opts\nfrom pyecharts.charts import Map\nfrom pyecharts.globals import CurrentConfig, NotebookType\nCurrentConfig.NOTEBOOK_TYPE = NotebookType.JUPYTER_LAB\n国内各地区现有确诊人数地图\n\nm = Map()\nm.add(\"\", [\n    list(z)\n    for z in zip(list(china_data[\"province\"]), list(china_data[\"nowConfirm\"]))\n],\n      maptype=\"china\",\n      is_map_symbol_show=False)\nm.set_global_opts(\n    title_opts=opts.TitleOpts(title=\"COVID-19中国现有地区现有确诊人数地图\"),\n    visualmap_opts=opts.VisualMapOpts(\n        is_piecewise=True,\n        pieces=[\n            {\n   \n                \"min\": 5000,\n                \"label\": ''>5000'',\n                \"color\": \"#893448\"\n            },  # 不指定 max，表示 max 为无限大\n            {\n   \n                \"min\": 1000,\n                \"max\": 4999,\n                \"label\": ''1000-4999'',\n                \"color\": \"#ff585e\"\n            },\n            {\n   \n                \"min\": 500,\n                \"max\": 999,\n                \"label\": ''500-1000'',\n                \"color\": \"#fb8146\"\n            },\n            {\n   \n                \"min\": 101,\n                \"max\": 499,\n                \"label\": ''101-499'',\n                \"color\": \"#ffA500\"\n            },\n            {\n   \n                \"min\": 10,\n                \"max\": 100,\n                \"label\": ''10-100'',\n                \"color\": \"#ffb248\"\n            },\n            {\n   \n                \"min\": 1,\n                \"max\": 9,\n                \"label\": ''1-9'',\n                \"color\": \"#fff2d1\"\n            },\n            {\n   \n                \"max\": 1,\n                \"label\": ''0'',\n                \"color\": \"#ffffff\"\n            }\n        ]))\nm.render_notebook()\n在这里插入图片描述\n\n4.2 国际疫情态势可视化\n将各国的中文名称转换成英文名称，使用pandas中的merge方法\n\npd.merge( left, right, how=‘inner’, on=None, left_on=None, right_on=None, left_index=False, right_index=False, sort=False, suffixes=(’_x’, ‘_y’), copy=True, indicator=False, validate=None,)\n\nhow: One of ‘left’, ‘right’, ‘outer’, ‘inner’. 默认inner。inner是取交集，outer取并集\n\nworld_name = pd.read_excel(\"国家中英文对照表.xlsx\")\nworld_data_t = pd.merge(world_data,\n                        world_name,\n                        left_on=\"country\",\n                        right_on=\"中文\",\n                        how=\"inner\")\n\nworld_data_t\ncountry\tnowConfirm\tconfirm\tdead\theal\t英文\t中文\n0\t美国\t7282611\t30358880\t552470\t22523799\tUnited States\t美国\n1\t西班牙\t193976\t3212332\t72910\t2945446\tSpain\t西班牙\n2\t法国\t2166003\t2405255\t57671\t181581\tFrance\t法国\n3\t秘鲁\t111940\t422183\t19408\t290835\tPeru\t秘鲁\n4\t英国\t90011\t104145\t13759\t375\tUnited Kingdom\t英国\n...\t...\t...\t...\t...\t...\t...\t...\n164\t伯利兹\t2\t2\t0\t0\tBelize\t伯利兹\n165\t东帝汶\t1\t1\t0\t0\tTimor-Leste\t东帝汶\n166\t东帝汶\t1\t1\t0\t0\tEast Timor\t东帝汶\n167\t巴布亚新几内亚\t1\t1\t0\t0\tPapua New Guinea\t巴布亚新几内亚\n168\t中国\t518\t102479\t4849\t97112\tChina\t中国\n169 rows × 7 columns\n\n世界各国现有确诊人数地图\n\nm2 = Map()\nm2.add(\"\", [\n    list(z)\n    for z in zip(list(world_data_t[\"英文\"]), list(world_data_t[\"nowConfirm\"]))\n],\n       maptype=\"world\",\n       is_map_symbol_show=False)\nm2.set_global_opts(title_opts=opts.TitleOpts(title=\"COVID-19世界各国现有确诊人数地图\"),\n                   visualmap_opts=opts.VisualMapOpts(is_piecewise=True,\n                                                     pieces=[{\n   \n                                                         \"min\": 5000,\n                                                         \"label\": ''>5000'',\n                                                         \"color\": \"#893448\"\n                                                     }, {\n   \n                                                         \"min\": 1000,\n                                                         \"max\": 4999,\n                                                         \"label\": ''1000-4999'',\n                                                         \"color\": \"#ff585e\"\n                                                     }, {\n   \n                                                         \"min\": 500,\n                                                         \"max\": 999,\n                                                         \"label\": ''500-1000'',\n                                                         \"color\": \"#fb8146\"\n                                                     }, {\n   \n                                                         \"min\": 101,\n                                                         \"max\": 499,\n                                                         \"label\": ''101-499'',\n                                                         \"color\": \"#ffA500\"\n                                                     }, {\n   \n                                                         \"min\": 10,\n                                                         \"max\": 100,\n                                                         \"label\": ''10-100'',\n                                                         \"color\": \"#ffb248\"\n                                                     }, {\n   \n                                                         \"min\": 0,\n                                                         \"max\": 9,\n                                                         \"label\": ''0-9'',\n                                                         \"color\": \"#fff2d1\"\n                                                     }]))\n\"\"\"取消显示国家名称\"\"\"\nm2.set_series_opts(label_opts=opts.LabelOpts(is_show=False))\nm2.render_notebook()\n在这里插入图片描述\n\n4.3 国内疫情方寸间\n单独取出中国疫情数据\n\n# 单独取出中国疫情数据\nChina_data = world_data.loc[world_data[''country''] == \"中国\"]\n\n# 使索引从0开始递增\nChina_data.reset_index(drop=True, inplace=True)\n\nChina_data\ncountry\tnowConfirm\tconfirm\tdead\theal\n0\t中国\t518\t102479\t4849\t97112\n提取China_data的累计确诊、累计治愈与累计死亡数据\n\n# 提取China_data的累计确诊、累计治愈与累计死亡数据\n# data.at[n,''name'']代表根据行索引和列名，获取对应元素的值\nw_confirm = China_data.at[0, ''confirm'']\nw_heal = China_data.at[0, ''heal'']\nw_dead = China_data.at[0, ''dead'']\n导入matplotlib相关库\n\nimport matplotlib.pyplot as plt\nimport matplotlib.patches as patches\n构建国内疫情方寸间图示\n\n# -*- coding: utf-8 -*-\n%matplotlib inline\n\nfig1 = plt.figure()\n\nax1 = fig1.add_subplot(111, aspect=''equal'', facecolor=''#fafaf0'')\nax1.set_xlim(-w_confirm / 2, w_confirm / 2)\nax1.set_ylim(-w_confirm / 2, w_confirm / 2)\nax1.spines[''top''].set_color(''none'')\nax1.spines[''right''].set_color(''none'')\nax1.spines[''bottom''].set_position((''data'', 0))\nax1.spines[''left''].set_position((''data'', 0))\nax1.set_xticks([])\nax1.set_yticks([])\n\np0 = patches.Rectangle((-w_confirm / 2, -w_confirm / 2),\n                       width=w_confirm,\n                       height=w_confirm,\n                       facecolor=''#29648c'',\n                       label=''confirm'')\np1 = patches.Rectangle((-w_heal / 2, -w_heal / 2),\n                       width=w_heal,\n                       height=w_heal,\n                       facecolor=''#69c864'',\n                       label=''heal'')\np2 = patches.Rectangle((-w_dead / 2, -w_dead / 2),\n                       width=w_dead,\n                       height=w_dead,\n                       facecolor=''#000000'',\n                       label=''dead'')\n\nplt.gca().add_patch(p0)\nplt.gca().add_patch(p1)\nplt.gca().add_patch(p2)\nplt.title(''COVID-19 Square - China'', fontdict={\n   ''size'': 20})\nplt.legend(loc=''best'')\nplt.show()\n在这里插入图片描述\n\n4.4 国际疫情方寸间\n重新排序数据\n\nworld_data.sort_values(\"confirm\", ascending=False, inplace=True)\nworld_data.reset_index(drop=True, inplace=True)\nworld_data\ncountry\tnowConfirm\tconfirm\tdead\theal\n0\t美国\t7282611\t30358880\t552470\t22523799\n1\t西班牙\t193976\t3212332\t72910\t2945446\n2\t法国\t2166003\t2405255\t57671\t181581\n3\t秘鲁\t111940\t422183\t19408\t290835\n4\t英国\t90011\t104145\t13759\t375\n...\t...\t...\t...\t...\t...\n157\t利比里亚\t3\t3\t0\t0\n158\t几内亚比绍\t2\t2\t0\t0\n159\t伯利兹\t2\t2\t0\t0\n160\t东帝汶\t1\t1\t0\t0\n161\t巴布亚新几内亚\t1\t1\t0\t0\n162 rows × 5 columns\n\n构建国际疫情方寸间图示\n\n# -*- coding: utf-8 -*-\nplt.rcParams[''font.sans-serif''] = [u''SimHei'']\nplt.rcParams[''axes.unicode_minus''] = False\nfig1 = plt.figure(figsize=(25, 25))\nfor a in range(20):\n\n    w_confirm = world_data.at[a, ''confirm'']\n    w_heal = world_data.at[a, ''heal'']\n    w_dead = world_data.at[a, ''dead'']\n    ax1 = fig1.add_subplot(20 / 4,\n                           4,\n                           a + 1,\n                           aspect=''equal'',\n                           facecolor=''#fafaf0'')\n    ax1.set_xlim(-w_confirm / 2, w_confirm / 2)\n    ax1.set_ylim(-w_confirm / 2, w_confirm / 2)\n\n    ax1.spines[''top''].set_color(''none'')\n    ax1.spines[''right''].set_color(''none'')\n    ax1.spines[''bottom''].set_position((''data'', 0))\n    ax1.spines[''left''].set_position((''data'', 0))\n    ax1.set_xticks([])\n    ax1.set_yticks([])\n    p0 = patches.Rectangle((-w_confirm / 2, -w_confirm / 2),\n                           width=w_confirm,\n                           height=w_confirm,\n                           alpha=w_confirm / 90000,\n                           facecolor=''#29648c'',\n                           label=''confirm'')\n    p1 = patches.Rectangle((-w_heal / 2, -w_heal / 2),\n                           width=w_heal,\n                           height=w_heal,\n                           alpha=1,\n                           facecolor=''#69c864'',\n                           label=''heal'')\n    p2 = patches.Rectangle((-w_dead / 2, -w_dead / 2),\n                           width=w_dead,\n                           height=w_dead,\n                           alpha=1,\n                           facecolor=''black'',\n                           label=''dead'')\n    plt.gca().add_patch(p0)\n    plt.gca().add_patch(p1)\n    plt.gca().add_patch(p2)\n\n\n    plt.title(world_data.at[a, ''country''], fontdict={\n   ''size'': 20})\n\n\n    plt.legend(loc=''best'')\n\nplt.show()\n在这里插入图片描述\n这样就可以清楚的看到各个国家新冠确诊人数、治愈和死亡人数的关系了","articleCover":"https://example-bucket.oss-cn-shanghai.aliyuncs.com/articles/09d3285df2b065db0f5be6b97126e3f8.jpg","articleTitle":"Python疫情数据爬取与可视化展示","categoryName":"后端","isFeatured":0,"isTop":0,"status":1,"tagNames":["疫情"],"type":1}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '演示账号', '172.17.0.1', '内网IP|内网IP', '2023-03-07 19:55:39', NULL);
INSERT INTO "public"."t_operation_log" OVERRIDING SYSTEM VALUE VALUES (1716, '文章模块', '新增或修改', '/admin/articles', 'com.aurora.controller.ArticleController.saveOrUpdateArticle', '保存和修改文章', '[{"articleContent":"疫情数据爬取与可视化展示\n使用Python爬取腾讯新闻疫情数据，并使用pyecharts可视化，绘制国内、国际日增长人数地图，matplotlib绘制方寸图。\n\n随笔记录所的所学，此博客为我记录文章所用，发布到此，仅供网友阅读参考。作者:北山啦\n\n写在前面：这个已经不是什么新鲜的话题了，所以请大佬勿喷\n\n文章目录\n疫情数据爬取与可视化展示\n1. 疫情数据抓取\n2. 初步分析\n3. 数据处理\n3.1 国内各省疫情数据提取\n3.2 国际疫情数据提取\n3.3 数据整合\n4. 可视化展示\n4.1 国内疫情态势可视化\n4.2 国际疫情态势可视化\n4.3 国内疫情方寸间\n4.4 国际疫情方寸间\n参考链接\n导入相关模块\n\nimport time\nimport json\nimport requests\nfrom datetime import datetime\nimport pandas as pd\nimport numpy as np\n1. 疫情数据抓取\n通过腾讯新闻公布的数据进行爬取\n\n网址:https://news.qq.com/zt2020/page/feiyan.htm#/\n\n对于静态网页，我们只需要把网页地址栏中的url传到get请求中就可以轻松地获取到网页的数据。 对于动态网页抓取的关键是先分析网页数据获取和跳转的逻辑，再去写代码 。\n\n右击检查，选择Network，Ctrl+R即可\n在这里插入图片描述\n\n# 定义抓取数据函数:https://beishan.blog.csdn.net/\ndef Domestic():\n    url = ''https://view.inews.qq.com/g2/getOnsInfo?name=disease_h5''\n    reponse = requests.get(url=url).json()\n    data = json.loads(reponse[''data''])\n    return data\n\n\ndef Oversea():\n    url = ''https://view.inews.qq.com/g2/getOnsInfo?name=disease_foreign''\n    reponse = requests.get(url=url).json()\n    data = json.loads(reponse[''data''])\n    return data\n\n\ndomestic = Domestic()\noversea = Oversea()\n\nprint(domestic.keys())\nprint(oversea.keys())\ndict_keys([''lastUpdateTime'', ''chinaTotal'', ''chinaAdd'', ''isShowAdd'', ''showAddSwitch'', ''areaTree''])\ndict_keys([''foreignList'', ''globalStatis'', ''globalDailyHistory'', ''importStatis'', ''countryAddConfirmRankList'', ''countryConfirmWeekCompareRankList'', ''continentStatis''])\n2. 初步分析\n提取各地区数据明细\n\n# 提取各地区数据明细\nareaTree = domestic[''areaTree'']\n# 查看并分析具体数据\nareaTree\n提取国外地区数据明细\n\n# 提取国外地区数据明细\nforeignList = oversea[''foreignList'']\n# 查看并分析具体数据\nforeignList\n就可以看到在json数据存储的结构了\n\n3. 数据处理\n3.1 国内各省疫情数据提取\n# Adresss：https://beishan.blog.csdn.net/\nchina_data = areaTree[0][''children''] \nchina_list = []\nfor a in range(len(china_data)):\n    province = china_data[a][''name'']  \n    confirm = china_data[a][''total''][''confirm''] \n    heal = china_data[a][''total''][''heal'']  \n    dead = china_data[a][''total''][''dead'']  \n    nowConfirm = confirm - heal - dead \n    china_dict = {\n   } \n    china_dict[''province''] = province  \n    china_dict[''nowConfirm''] = nowConfirm \n    china_list.append(china_dict) \n\nchina_data = pd.DataFrame(china_list) \nchina_data.to_excel(\"国内疫情.xlsx\", index=False) #存储为EXCEL文件\nchina_data.head()\nprovince\tnowConfirm\n0\t香港\t323\n1\t上海\t40\n2\t四川\t34\n3\t台湾\t30\n4\t广东\t29\n3.2 国际疫情数据提取\nworld_data = foreignList  \nworld_list = []  \n\nfor a in range(len(world_data)):\n    # 提取数据\n    country = world_data[a][''name'']\n    nowConfirm = world_data[a][''nowConfirm'']  \n    confirm = world_data[a][''confirm'']\n    dead = world_data[a][''dead'']  \n    heal = world_data[a][''heal''] \n    # 存放数据\n    world_dict = {\n   }\n    world_dict[''country''] = country\n    world_dict[''nowConfirm''] = nowConfirm\n    world_dict[''confirm''] = confirm\n    world_dict[''dead''] = dead\n    world_dict[''heal''] = heal\n    world_list.append(world_dict)\n\nworld_data = pd.DataFrame(world_list)\nworld_data.to_excel(\"国外疫情.xlsx\", index=False)\nworld_data.head()\ncountry\tnowConfirm\tconfirm\tdead\theal\n0\t美国\t7282611\t30358880\t552470\t22523799\n1\t西班牙\t193976\t3212332\t72910\t2945446\n2\t法国\t2166003\t2405255\t57671\t181581\n3\t秘鲁\t111940\t422183\t19408\t290835\n4\t英国\t90011\t104145\t13759\t375\n3.3 数据整合\n将国内数据和海外数据合并\n\n查询数据中是否含有中国疫情数据\n\nworld_data.loc[world_data[''country''] == \"中国\"]\ncountry\tnowConfirm\tconfirm\tdead\theal\n从新增areaTree中提取中国数据，并添加至world_data\n\nconfirm = areaTree[0][''total''][''confirm'']  # 提取中国累计确诊数据\nheal = areaTree[0][''total''][''heal'']  # 提取中国累计治愈数据\ndead = areaTree[0][''total''][''dead'']  # 提取中国累计死亡数据\nnowConfirm = confirm - heal - dead  # 计算中国现有确诊数量\n\nworld_data = world_data.append(\n    {\n   \n        ''country'': \"中国\",\n        ''nowConfirm'': nowConfirm,\n        ''confirm'': confirm,\n        ''heal'': heal,\n        ''dead'': dead\n    },\n    ignore_index=True)\n再次查询数据中是否含有中国疫情数据\n\nworld_data.loc[world_data[''country''] == \"中国\"]\ncountry\tnowConfirm\tconfirm\tdead\theal\n161\t中国\t518\t102479\t4849\t97112\n4. 可视化展示\n4.1 国内疫情态势可视化\n导入pyecharts相关库\n\nimport pyecharts.options as opts\nfrom pyecharts.charts import Map\nfrom pyecharts.globals import CurrentConfig, NotebookType\nCurrentConfig.NOTEBOOK_TYPE = NotebookType.JUPYTER_LAB\n国内各地区现有确诊人数地图\n\nm = Map()\nm.add(\"\", [\n    list(z)\n    for z in zip(list(china_data[\"province\"]), list(china_data[\"nowConfirm\"]))\n],\n      maptype=\"china\",\n      is_map_symbol_show=False)\nm.set_global_opts(\n    title_opts=opts.TitleOpts(title=\"COVID-19中国现有地区现有确诊人数地图\"),\n    visualmap_opts=opts.VisualMapOpts(\n        is_piecewise=True,\n        pieces=[\n            {\n   \n                \"min\": 5000,\n                \"label\": ''>5000'',\n                \"color\": \"#893448\"\n            },  # 不指定 max，表示 max 为无限大\n            {\n   \n                \"min\": 1000,\n                \"max\": 4999,\n                \"label\": ''1000-4999'',\n                \"color\": \"#ff585e\"\n            },\n            {\n   \n                \"min\": 500,\n                \"max\": 999,\n                \"label\": ''500-1000'',\n                \"color\": \"#fb8146\"\n            },\n            {\n   \n                \"min\": 101,\n                \"max\": 499,\n                \"label\": ''101-499'',\n                \"color\": \"#ffA500\"\n            },\n            {\n   \n                \"min\": 10,\n                \"max\": 100,\n                \"label\": ''10-100'',\n                \"color\": \"#ffb248\"\n            },\n            {\n   \n                \"min\": 1,\n                \"max\": 9,\n                \"label\": ''1-9'',\n                \"color\": \"#fff2d1\"\n            },\n            {\n   \n                \"max\": 1,\n                \"label\": ''0'',\n                \"color\": \"#ffffff\"\n            }\n        ]))\nm.render_notebook()\n在这里插入图片描述\n\n4.2 国际疫情态势可视化\n将各国的中文名称转换成英文名称，使用pandas中的merge方法\n\npd.merge( left, right, how=‘inner’, on=None, left_on=None, right_on=None, left_index=False, right_index=False, sort=False, suffixes=(’_x’, ‘_y’), copy=True, indicator=False, validate=None,)\n\nhow: One of ‘left’, ‘right’, ‘outer’, ‘inner’. 默认inner。inner是取交集，outer取并集\n\nworld_name = pd.read_excel(\"国家中英文对照表.xlsx\")\nworld_data_t = pd.merge(world_data,\n                        world_name,\n                        left_on=\"country\",\n                        right_on=\"中文\",\n                        how=\"inner\")\n\nworld_data_t\ncountry\tnowConfirm\tconfirm\tdead\theal\t英文\t中文\n0\t美国\t7282611\t30358880\t552470\t22523799\tUnited States\t美国\n1\t西班牙\t193976\t3212332\t72910\t2945446\tSpain\t西班牙\n2\t法国\t2166003\t2405255\t57671\t181581\tFrance\t法国\n3\t秘鲁\t111940\t422183\t19408\t290835\tPeru\t秘鲁\n4\t英国\t90011\t104145\t13759\t375\tUnited Kingdom\t英国\n...\t...\t...\t...\t...\t...\t...\t...\n164\t伯利兹\t2\t2\t0\t0\tBelize\t伯利兹\n165\t东帝汶\t1\t1\t0\t0\tTimor-Leste\t东帝汶\n166\t东帝汶\t1\t1\t0\t0\tEast Timor\t东帝汶\n167\t巴布亚新几内亚\t1\t1\t0\t0\tPapua New Guinea\t巴布亚新几内亚\n168\t中国\t518\t102479\t4849\t97112\tChina\t中国\n169 rows × 7 columns\n\n世界各国现有确诊人数地图\n\nm2 = Map()\nm2.add(\"\", [\n    list(z)\n    for z in zip(list(world_data_t[\"英文\"]), list(world_data_t[\"nowConfirm\"]))\n],\n       maptype=\"world\",\n       is_map_symbol_show=False)\nm2.set_global_opts(title_opts=opts.TitleOpts(title=\"COVID-19世界各国现有确诊人数地图\"),\n                   visualmap_opts=opts.VisualMapOpts(is_piecewise=True,\n                                                     pieces=[{\n   \n                                                         \"min\": 5000,\n                                                         \"label\": ''>5000'',\n                                                         \"color\": \"#893448\"\n                                                     }, {\n   \n                                                         \"min\": 1000,\n                                                         \"max\": 4999,\n                                                         \"label\": ''1000-4999'',\n                                                         \"color\": \"#ff585e\"\n                                                     }, {\n   \n                                                         \"min\": 500,\n                                                         \"max\": 999,\n                                                         \"label\": ''500-1000'',\n                                                         \"color\": \"#fb8146\"\n                                                     }, {\n   \n                                                         \"min\": 101,\n                                                         \"max\": 499,\n                                                         \"label\": ''101-499'',\n                                                         \"color\": \"#ffA500\"\n                                                     }, {\n   \n                                                         \"min\": 10,\n                                                         \"max\": 100,\n                                                         \"label\": ''10-100'',\n                                                         \"color\": \"#ffb248\"\n                                                     }, {\n   \n                                                         \"min\": 0,\n                                                         \"max\": 9,\n                                                         \"label\": ''0-9'',\n                                                         \"color\": \"#fff2d1\"\n                                                     }]))\n\"\"\"取消显示国家名称\"\"\"\nm2.set_series_opts(label_opts=opts.LabelOpts(is_show=False))\nm2.render_notebook()\n在这里插入图片描述\n\n4.3 国内疫情方寸间\n单独取出中国疫情数据\n\n# 单独取出中国疫情数据\nChina_data = world_data.loc[world_data[''country''] == \"中国\"]\n\n# 使索引从0开始递增\nChina_data.reset_index(drop=True, inplace=True)\n\nChina_data\ncountry\tnowConfirm\tconfirm\tdead\theal\n0\t中国\t518\t102479\t4849\t97112\n提取China_data的累计确诊、累计治愈与累计死亡数据\n\n# 提取China_data的累计确诊、累计治愈与累计死亡数据\n# data.at[n,''name'']代表根据行索引和列名，获取对应元素的值\nw_confirm = China_data.at[0, ''confirm'']\nw_heal = China_data.at[0, ''heal'']\nw_dead = China_data.at[0, ''dead'']\n导入matplotlib相关库\n\nimport matplotlib.pyplot as plt\nimport matplotlib.patches as patches\n构建国内疫情方寸间图示\n\n# -*- coding: utf-8 -*-\n%matplotlib inline\n\nfig1 = plt.figure()\n\nax1 = fig1.add_subplot(111, aspect=''equal'', facecolor=''#fafaf0'')\nax1.set_xlim(-w_confirm / 2, w_confirm / 2)\nax1.set_ylim(-w_confirm / 2, w_confirm / 2)\nax1.spines[''top''].set_color(''none'')\nax1.spines[''right''].set_color(''none'')\nax1.spines[''bottom''].set_position((''data'', 0))\nax1.spines[''left''].set_position((''data'', 0))\nax1.set_xticks([])\nax1.set_yticks([])\n\np0 = patches.Rectangle((-w_confirm / 2, -w_confirm / 2),\n                       width=w_confirm,\n                       height=w_confirm,\n                       facecolor=''#29648c'',\n                       label=''confirm'')\np1 = patches.Rectangle((-w_heal / 2, -w_heal / 2),\n                       width=w_heal,\n                       height=w_heal,\n                       facecolor=''#69c864'',\n                       label=''heal'')\np2 = patches.Rectangle((-w_dead / 2, -w_dead / 2),\n                       width=w_dead,\n                       height=w_dead,\n                       facecolor=''#000000'',\n                       label=''dead'')\n\nplt.gca().add_patch(p0)\nplt.gca().add_patch(p1)\nplt.gca().add_patch(p2)\nplt.title(''COVID-19 Square - China'', fontdict={\n   ''size'': 20})\nplt.legend(loc=''best'')\nplt.show()\n在这里插入图片描述\n\n4.4 国际疫情方寸间\n重新排序数据\n\nworld_data.sort_values(\"confirm\", ascending=False, inplace=True)\nworld_data.reset_index(drop=True, inplace=True)\nworld_data\ncountry\tnowConfirm\tconfirm\tdead\theal\n0\t美国\t7282611\t30358880\t552470\t22523799\n1\t西班牙\t193976\t3212332\t72910\t2945446\n2\t法国\t2166003\t2405255\t57671\t181581\n3\t秘鲁\t111940\t422183\t19408\t290835\n4\t英国\t90011\t104145\t13759\t375\n...\t...\t...\t...\t...\t...\n157\t利比里亚\t3\t3\t0\t0\n158\t几内亚比绍\t2\t2\t0\t0\n159\t伯利兹\t2\t2\t0\t0\n160\t东帝汶\t1\t1\t0\t0\n161\t巴布亚新几内亚\t1\t1\t0\t0\n162 rows × 5 columns\n\n构建国际疫情方寸间图示\n\n# -*- coding: utf-8 -*-\nplt.rcParams[''font.sans-serif''] = [u''SimHei'']\nplt.rcParams[''axes.unicode_minus''] = False\nfig1 = plt.figure(figsize=(25, 25))\nfor a in range(20):\n\n    w_confirm = world_data.at[a, ''confirm'']\n    w_heal = world_data.at[a, ''heal'']\n    w_dead = world_data.at[a, ''dead'']\n    ax1 = fig1.add_subplot(20 / 4,\n                           4,\n                           a + 1,\n                           aspect=''equal'',\n                           facecolor=''#fafaf0'')\n    ax1.set_xlim(-w_confirm / 2, w_confirm / 2)\n    ax1.set_ylim(-w_confirm / 2, w_confirm / 2)\n\n    ax1.spines[''top''].set_color(''none'')\n    ax1.spines[''right''].set_color(''none'')\n    ax1.spines[''bottom''].set_position((''data'', 0))\n    ax1.spines[''left''].set_position((''data'', 0))\n    ax1.set_xticks([])\n    ax1.set_yticks([])\n    p0 = patches.Rectangle((-w_confirm / 2, -w_confirm / 2),\n                           width=w_confirm,\n                           height=w_confirm,\n                           alpha=w_confirm / 90000,\n                           facecolor=''#29648c'',\n                           label=''confirm'')\n    p1 = patches.Rectangle((-w_heal / 2, -w_heal / 2),\n                           width=w_heal,\n                           height=w_heal,\n                           alpha=1,\n                           facecolor=''#69c864'',\n                           label=''heal'')\n    p2 = patches.Rectangle((-w_dead / 2, -w_dead / 2),\n                           width=w_dead,\n                           height=w_dead,\n                           alpha=1,\n                           facecolor=''black'',\n                           label=''dead'')\n    plt.gca().add_patch(p0)\n    plt.gca().add_patch(p1)\n    plt.gca().add_patch(p2)\n\n\n    plt.title(world_data.at[a, ''country''], fontdict={\n   ''size'': 20})\n\n\n    plt.legend(loc=''best'')\n\nplt.show()\n在这里插入图片描述\n这样就可以清楚的看到各个国家新冠确诊人数、治愈和死亡人数的关系了","articleCover":"https://example-bucket.oss-cn-shanghai.aliyuncs.com/articles/09d3285df2b065db0f5be6b97126e3f8.jpg","articleTitle":"Python疫情数据爬取与可视化展示","categoryName":"后端","id":139,"isFeatured":0,"isTop":0,"status":1,"tagNames":[],"type":2}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '演示账号', '172.17.0.1', '内网IP|内网IP', '2023-03-07 19:56:19', NULL);
INSERT INTO "public"."t_operation_log" OVERRIDING SYSTEM VALUE VALUES (1717, '文章模块', '新增或修改', '/admin/articles', 'com.aurora.controller.ArticleController.saveOrUpdateArticle', '保存和修改文章', '[{"articleContent":"<div style=\"border:1px solid #ccc; border-top:none; height:100%; z-index:100; max-height:115px;\" class=\"w-e-text-container\"><div contenteditable=\"true\" style=\"width:100%; height:100%;\" class=\"w-e-text\" id=\"text-elem6695893280797052\"><svg xmlns=\"http://www.w3.org/2000/svg\" style=\"display: none;\"> \n <path stroke-linecap=\"round\" d=\"M5,0 0,2.5 5,5z\" id=\"raphael-marker-block\" style=\"-webkit-tap-highlight-color: rgba(0, 0, 0, 0);\"></path> \n</svg> \n<h1><a id=\"httpsbeishanblogcsdnnetarticledetails115017160_0\"></a><a href=\"https://beishan.blog.csdn.net/article/details/115017160\">疫情数据爬取与可视化展示</a></h1> \n<p>使用Python爬取腾讯新闻疫情数据，并使用pyecharts可视化，绘制国内、国际日增长人数地图，matplotlib绘制方寸图。</p> \n<blockquote> \n <p>随笔记录所的所学，此博客为我记录文章所用，发布到此，仅供网友阅读参考。作者:北山啦</p> \n</blockquote> \n<blockquote> \n <p><code>写在前面</code>：这个已经不是什么新鲜的话题了，所以请大佬勿喷</p> \n</blockquote> \n<p></p> \n<div class=\"toc\"> \n <h3>文章目录</h3> \n <ul>\n  <li><a href=\"#httpsbeishanblogcsdnnetarticledetails115017160_0\">疫情数据爬取与可视化展示</a></li>\n  <li><a href=\"#1__22\">1. 疫情数据抓取</a></li>\n  <li><a href=\"#2__60\">2. 初步分析</a></li>\n  <li><a href=\"#3__82\">3. 数据处理</a></li>\n  <li>\n   <ul>\n    <li><a href=\"#31__84\">3.1 国内各省疫情数据提取</a></li>\n    <li><a href=\"#32__164\">3.2 国际疫情数据提取</a></li>\n    <li><a href=\"#33__267\">3.3 数据整合</a></li>\n   </ul> </li>\n  <li><a href=\"#4__382\">4. 可视化展示</a></li>\n  <li>\n   <ul>\n    <li><a href=\"#41__384\">4.1 国内疫情态势可视化</a></li>\n    <li><a href=\"#42__461\">4.2 国际疫情态势可视化</a></li>\n    <li><a href=\"#43__682\">4.3 国内疫情方寸间</a></li>\n    <li><a href=\"#44__808\">4.4 国际疫情方寸间</a></li>\n   </ul> </li>\n  <li><a href=\"#_1020\">参考链接</a></li>\n </ul> \n</div> \n<p></p> \n<p>导入相关模块</p> \n<pre><code class=\"prism language-python\"><span class=\"token keyword\">import</span> time\n<span class=\"token keyword\">import</span> json\n<span class=\"token keyword\">import</span> requests\n<span class=\"token keyword\">from</span> datetime <span class=\"token keyword\">import</span> datetime\n<span class=\"token keyword\">import</span> pandas <span class=\"token keyword\">as</span> pd\n<span class=\"token keyword\">import</span> numpy <span class=\"token keyword\">as</span> np\n</code></pre> \n<h1><a id=\"1__22\"></a>1. 疫情数据抓取</h1> \n<p>通过腾讯新闻公布的数据进行爬取</p> \n<p>网址:https://news.qq.com/zt2020/page/feiyan.htm#/</p> \n<blockquote> \n <p>对于静态网页，我们只需要把网页地址栏中的url传到get请求中就可以轻松地获取到网页的数据。 对于动态网页抓取的关键是先分析网页数据获取和跳转的逻辑，再去写代码 。</p> \n</blockquote> \n<p>右击检查，选择Network，Ctrl+R即可<br> <img src=\"https://img-blog.csdnimg.cn/20210319221913201.gif#pic_center\" title=\"\" alt=\"在这里插入图片描述\"></p> \n<pre><code class=\"prism language-python\"><span class=\"token comment\"># 定义抓取数据函数:https://beishan.blog.csdn.net/</span>\n<span class=\"token keyword\">def</span> <span class=\"token function\">Domestic</span><span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span><span class=\"token punctuation\">:</span>\n    url <span class=\"token operator\">=</span> <span class=\"token string\">''https://view.inews.qq.com/g2/getOnsInfo?name=disease_h5''</span>\n    reponse <span class=\"token operator\">=</span> requests<span class=\"token punctuation\">.</span>get<span class=\"token punctuation\">(</span>url<span class=\"token operator\">=</span>url<span class=\"token punctuation\">)</span><span class=\"token punctuation\">.</span>json<span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span>\n    data <span class=\"token operator\">=</span> json<span class=\"token punctuation\">.</span>loads<span class=\"token punctuation\">(</span>reponse<span class=\"token punctuation\">[</span><span class=\"token string\">''data''</span><span class=\"token punctuation\">]</span><span class=\"token punctuation\">)</span>\n    <span class=\"token keyword\">return</span> data\n\n\n<span class=\"token keyword\">def</span> <span class=\"token function\">Oversea</span><span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span><span class=\"token punctuation\">:</span>\n    url <span class=\"token operator\">=</span> <span class=\"token string\">''https://view.inews.qq.com/g2/getOnsInfo?name=disease_foreign''</span>\n    reponse <span class=\"token operator\">=</span> requests<span class=\"token punctuation\">.</span>get<span class=\"token punctuation\">(</span>url<span class=\"token operator\">=</span>url<span class=\"token punctuation\">)</span><span class=\"token punctuation\">.</span>json<span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span>\n    data <span class=\"token operator\">=</span> json<span class=\"token punctuation\">.</span>loads<span class=\"token punctuation\">(</span>reponse<span class=\"token punctuation\">[</span><span class=\"token string\">''data''</span><span class=\"token punctuation\">]</span><span class=\"token punctuation\">)</span>\n    <span class=\"token keyword\">return</span> data\n\n\ndomestic <span class=\"token operator\">=</span> Domestic<span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span>\noversea <span class=\"token operator\">=</span> Oversea<span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span>\n\n<span class=\"token keyword\">print</span><span class=\"token punctuation\">(</span>domestic<span class=\"token punctuation\">.</span>keys<span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span><span class=\"token punctuation\">)</span>\n<span class=\"token keyword\">print</span><span class=\"token punctuation\">(</span>oversea<span class=\"token punctuation\">.</span>keys<span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span><span class=\"token punctuation\">)</span>\n</code></pre> \n<pre><code>dict_keys([''lastUpdateTime'', ''chinaTotal'', ''chinaAdd'', ''isShowAdd'', ''showAddSwitch'', ''areaTree''])\ndict_keys([''foreignList'', ''globalStatis'', ''globalDailyHistory'', ''importStatis'', ''countryAddConfirmRankList'', ''countryConfirmWeekCompareRankList'', ''continentStatis''])\n</code></pre> \n<h1><a id=\"2__60\"></a>2. 初步分析</h1> \n<p>提取各地区数据明细</p> \n<pre><code class=\"prism language-python\"><span class=\"token comment\"># 提取各地区数据明细</span>\nareaTree <span class=\"token operator\">=</span> domestic<span class=\"token punctuation\">[</span><span class=\"token string\">''areaTree''</span><span class=\"token punctuation\">]</span>\n<span class=\"token comment\"># 查看并分析具体数据</span>\nareaTree\n</code></pre> \n<p>提取国外地区数据明细</p> \n<pre><code class=\"prism language-python\"><span class=\"token comment\"># 提取国外地区数据明细</span>\nforeignList <span class=\"token operator\">=</span> oversea<span class=\"token punctuation\">[</span><span class=\"token string\">''foreignList''</span><span class=\"token punctuation\">]</span>\n<span class=\"token comment\"># 查看并分析具体数据</span>\nforeignList\n</code></pre> \n<p>就可以看到在json数据存储的结构了</p> \n<h1><a id=\"3__82\"></a>3. 数据处理</h1> \n<h2><a id=\"31__84\"></a>3.1 国内各省疫情数据提取</h2> \n<pre><code class=\"prism language-python\"><span class=\"token comment\"># Adresss：https://beishan.blog.csdn.net/</span>\nchina_data <span class=\"token operator\">=</span> areaTree<span class=\"token punctuation\">[</span><span class=\"token number\">0</span><span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''children''</span><span class=\"token punctuation\">]</span> \nchina_list <span class=\"token operator\">=</span> <span class=\"token punctuation\">[</span><span class=\"token punctuation\">]</span>\n<span class=\"token keyword\">for</span> a <span class=\"token keyword\">in</span> <span class=\"token builtin\">range</span><span class=\"token punctuation\">(</span><span class=\"token builtin\">len</span><span class=\"token punctuation\">(</span>china_data<span class=\"token punctuation\">)</span><span class=\"token punctuation\">)</span><span class=\"token punctuation\">:</span>\n    province <span class=\"token operator\">=</span> china_data<span class=\"token punctuation\">[</span>a<span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''name''</span><span class=\"token punctuation\">]</span>  \n    confirm <span class=\"token operator\">=</span> china_data<span class=\"token punctuation\">[</span>a<span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''total''</span><span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''confirm''</span><span class=\"token punctuation\">]</span> \n    heal <span class=\"token operator\">=</span> china_data<span class=\"token punctuation\">[</span>a<span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''total''</span><span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''heal''</span><span class=\"token punctuation\">]</span>  \n    dead <span class=\"token operator\">=</span> china_data<span class=\"token punctuation\">[</span>a<span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''total''</span><span class=\"token punctuation\">]</span><span class=\"token punctuation\">[</span><span class=\"token string\">''dead''</span><span class=\"token punctuation\">]</span>  \n    nowConfirm <span class=\"token operator\">=</span> confirm <span class=\"token operator\">-</span> heal <span class=\"token operator\">-</span> dead \n    china_dict <span class=\"token operator\">=</span> <span class=\"token punctuation\">{\n   <!-- --></span><span class=\"token punctuation\">}</span> \n    china_dict<span class=\"token punctuation\">[</span><span class=\"token string\">''province''</span><span class=\"token punctuation\">]</span> <span class=\"token operator\">=</span> province  \n    china_dict<span class=\"token punctuation\">[</span><span class=\"token string\">''nowConfirm''</span><span class=\"token punctuation\">]</span> <span class=\"token operator\">=</span> nowConfirm \n    china_list<span class=\"token punctuation\">.</span>append<span class=\"token punctuation\">(</span>china_dict<span class=\"token punctuation\">)</span> \n\nchina_data <span class=\"token operator\">=</span> pd<span class=\"token punctuation\">.</span>DataFrame<span class=\"token punctuation\">(</span>china_list<span class=\"token punctuation\">)</span> \nchina_data<span class=\"token punctuation\">.</span>to_excel<span class=\"token punctuation\">(</span><span class=\"token string\">\"国内疫情.xlsx\"</span><span class=\"token punctuation\">,</span> index<span class=\"token operator\">=</span><span class=\"token boolean\">False</span><span class=\"token punctuation\">)</span> <span class=\"token comment\">#存储为EXCEL文件</span>\nchina_data<span class=\"token punctuation\">.</span>head<span class=\"token punctuation\">(</span><span class=\"token punctuation\">)</span>\n</code></pre> \n<div> \n</div> \n<table border=\"1\" class=\"dataframe\">\n <thead>\n  <tr>\n   <th></th>\n   <th>province</th>\n   <th>nowConfirm</th>\n  </tr>\n </thead>\n <tbody>\n  <tr>\n   <th>0</th>\n   <td>香港</td>\n   <td>323</td>\n  </tr>\n  <tr>\n   <th>1</th>\n   <td>上海</td>\n   <td>40</td>\n  </tr>\n  <tr>\n   <th>2</th>\n   <td>四川</td>\n   <td>34</td>\n  </tr>\n  <tr>\n   <th>3</th>\n   <td>台湾</td>\n   <td>30</td>\n  </tr>\n  <tr>\n   <th>4</th>\n   <td>广东</td>\n   <td>29</td>\n  </tr>\n </tbody>\n</table> \n<h2><a id=\"32__164\"></a>3.2 国际疫情数据提取</h2> \n<pre><code class=\"prism language-python\">world_data <span class=\"token operator\">=</span> foreignList  \nworld_list <span class=\"token operator\">=</span>