INSERT INTO "public"."t_talk" OVERRIDING SYSTEM VALUE VALUES (4, 1, '四马身大胜日本杯，G1 6连胜！秋皇的伟大，无需多言。', '', 1, 1, '2023-11-26 07:47:47', '2024-04-08 21:49:06');
INSERT INTO "public"."t_talk" OVERRIDING SYSTEM VALUE VALUES (71, 1, '恭喜初日高升三战三胜，1穿16无败皋月，达成了去年大哥春秋分的遗憾，也为老爹北黑献上第一个经典赛事g1，同时也是北黑产驹中央累计地一百胜', '["https://example.invalid/removed"]', 0, 1, '2023-04-19 05:15:34', '2023-04-19 05:20:39');
INSERT INTO "public"."t_talk" OVERRIDING SYSTEM VALUE VALUES (75, 1, '终于决定放弃门了吗，派了三匹酱油（doge', '["https://example.invalid/removed","http://i.example.invalid/talks/863cf67d768b328e0b0df519829a130d.png","http://i.example.invalid/talks/fdb0b33001a7f3b719ef01e92b350742.png","http://i.example.invalid/talks/55454fcb130967364d23ea1cda2af876.png"]', 0, 1, '2023-05-23 07:17:59', '2023-05-23 07:17:59');
INSERT INTO "public"."t_talk" OVERRIDING SYSTEM VALUE VALUES (76, 1, '小横山还是太年轻了呀，最后弯道坐包厢，被堵的严严实实的，连续两年颈差落败；以为是武丰再来，结果是福永再来...
', '["https://example.invalid/removed"]', 0, 1, '2023-05-28 08:06:00', '2023-05-28 08:25:35');
INSERT INTO "public"."t_talk" OVERRIDING SYSTEM VALUE VALUES (77, 1, '这德比不跑也罢，太伤马了，木村你坏事做尽，Skilfing走好', '["https://example.invalid/removed"]', 0, 1, '2023-05-28 08:24:42', '2023-06-09 06:51:43');
INSERT INTO "public"."t_talk" OVERRIDING SYSTEM VALUE VALUES (2, 1, '出闸失利，中段坐包厢，但是1穿14 --G1 4连胜，大外强袭，没有技巧，只有实力！', '["https://example.invalid/removed"]', 0, 1, '2023-06-25 09:01:23', '2023-06-25 09:01:23');
INSERT INTO "public"."t_talk" OVERRIDING SYSTEM VALUE VALUES (3, 1, '我居然会担心秋皇的陨落，秋门，破纪录的强大！', '["https://example.invalid/removed"]', 0, 1, '2023-10-29 09:01:30', '2024-04-08 21:47:47');

